text:
{
  "explanation_abstained": false,
  "relevance": true,
  "claims": [
    {
      "claim": "Propranolol acts as a non-selective β-adrenergic receptor antagonist.",
      "verdict": "SUPPORTED",
      "rationale": "PMID 34650198 and 33558238 both explicitly state that propranolol is a non-selective β-adrenergic receptor antagonist."
    },
    {
      "claim": "Propranolol inhibits the proliferation of hemangioma endothelial cells (HemECs) by blocking ADRB2 signaling.",
      "verdict": "SUPPORTED",
      "rationale": "PMID 34650198 states that propranolol inhibits the proliferation of HemECs through acting on β2-adrenoceptors (among others)."
    },
    {
      "claim": "Propranolol modulates the crosstalk between lesional vascular cells and stromal cells, such as mast cells and telocytes.",
      "verdict": "SUPPORTED",
      "rationale": "PMID 34650198 discusses the role of mast cells, and PMID 33558238 discusses the role of telocytes in the response to propranolol."
    },
    {
      "claim": "The inhibition of ADRB2 by propranolol triggers the downregulation of Aquaporin-1.",
      "verdict": "SUPPORTED",
      "rationale": "PMID 33558238 indicates that propranolol treatment and AQP1 down-regulation trigger the same pathway and that modulation of AQP1 in IH-TC by propranolol decreases angiogenesis."
    },
    {
      "claim": "Propranolol promotes apoptosis and autophagy in infantile hemangioma.",
      "verdict": "SUPPORTED",
      "rationale": "PMID 34650198 explicitly states that apoptosis and autophagy were induced in HemECs treated with propranolol-treated HMC-1s supernatants."
    },
    {
      "claim": "Propranolol suppresses pro-angiogenic and inflammatory signaling required for infantile hemangioma growth.",
      "verdict": "SUPPORTED",
      "rationale": "PMID 34650198 notes the reduction of cytokines/mediators and inhibition of angiogenic capacity; PMID 35163250 (though focused on ccRCC) supports the general mechanism of ADRB2 blockade reducing inflammation."
    }
  ]
}
